import { createHash } from 'node:crypto'

function encode(bytes) {
  return Buffer.from(bytes).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}
function hash(input) {
  const digest = createHash('sha256').update(input).digest()
  return encode(digest.subarray(0, 12))
}
function rscParam(prefetch, segment, stateTree, nextUrl) {
  if ((prefetch === undefined || prefetch === '0') && segment === undefined && stateTree === undefined && nextUrl === undefined) return ''
  const input = [prefetch ?? '0', segment ?? '0', stateTree ?? '0', nextUrl ?? '0'].join(',')
  return hash(input)
}

async function hit(label, headers) {
  const prefetch = headers['next-router-prefetch']
  const segment = headers['next-router-segment-prefetch']
  const state = headers['next-router-state-tree']
  const nextUrl = headers['next-url']
  const param = rscParam(prefetch, segment, state, nextUrl)
  const url = `http://localhost:3456/projects/acme${param ? `?_rsc=${param}` : ''}`
  const res = await fetch(url, { headers, redirect: 'manual' })
  const text = await res.text()
  const interesting = ['Acme Storefront', 'Commerce storefront', 'Production deployment', 'Loading project', 'Recent activity', 'Orbit Analytics']
  const found = Object.fromEntries(interesting.map(s => [s, text.includes(s)]))
  console.log('\n===', label, res.status, res.headers.get('content-type'), 'len', text.length, '===')
  console.log('location', res.headers.get('location'))
  console.log('x-nextjs-postponed', res.headers.get('x-nextjs-postponed'))
  console.log('found', found)
  console.log(text.slice(0, 800).replace(/\n/g, ' | '))
}

const base = { rsc: '1', accept: 'text/x-component' }
await hit('nav', base)
await hit('prefetch-1', { ...base, 'next-router-prefetch': '1' })
await hit('prefetch-2', { ...base, 'next-router-prefetch': '2' })
await hit('prefetch-3', { ...base, 'next-router-prefetch': '3' })
await hit('segment-tree', { ...base, 'next-router-prefetch': '1', 'next-router-segment-prefetch': '/_tree' })
EOF

